static std::string generateShowtimesSQL() {
    if (showtime_seeds.empty()) return "";
    const auto now = std::chrono::system_clock::now();
    std::time_t now_t = std::chrono::system_clock::to_time_t(now);
    std::tm tm_today = *std::localtime(&now_t);
    tm_today.tm_hour = 0;
    tm_today.tm_min = 0;
    tm_today.tm_sec = 0;
    const auto today_start_t = std::mktime(&tm_today);
    const auto today = std::chrono::system_clock::from_time_t(today_start_t);
    std::stringstream sql;
    sql << "INSERT INTO Showtimes (MovieID, VenueID, AuditoriumID, ShowtimeDateTime) VALUES ";
    for (size_t i = 0; i < showtime_seeds.size(); ++i) {
        const auto& seed = showtime_seeds[i];
        const auto target_day = today + std::chrono::hours(24*seed.day_offset);
        std::time_t target_time_t = std::chrono::system_clock::to_time_t(target_day);
        std::tm tm = *std::localtime(&target_time_t);
        char date_buffer[11]; // For "YYYY-MM-DD" + null terminator
        std::strftime(date_buffer, sizeof(date_buffer), "%Y-%m-%d", &tm);
        sql << "(" << seed.movie_id << ", " << seed.venue_id << ", " << seed.auditorium_id << ", "
            << "'" << date_buffer << " " << seed.time << "')";
        if (i < showtime_seeds.size() - 1) sql << ",\n";
    }
    sql << ";";
    return sql.str();
}

